def load(src):
    d = {}
    for line in open('/home/user/church/bible/raw/%s/%s_vpl.txt' % (src, src), encoding='utf-8'):
        m = re.match(r'^(\w{3}) (\d+):(\d+) (.*)$', line.rstrip('\n'))
        if m: d[(m.group(1), int(m.group(2)), int(m.group(3)))] = m.group(4).replace('¶', '').strip()
    return d
